#!/usr/bin/env python3
from pathlib import Path

root = Path(__file__).resolve().parents[1]
vendor = root / "mixins" / "simple-voice-chat" / "crates" / "svc_client" / "vendor"
output = root / "src" / "svc_client" / "opus_sources.rs"

if not (vendor / "src" / "opus.c").is_file():
    raise SystemExit("Vendored libopus sources are missing")

lines = [
    "// Generated by tools/prepare_native.py.",
    "// Source files are hex-encoded because native .hmod packages carry Rust source only.",
]
for path in sorted(p for p in vendor.rglob("*") if p.is_file()):
    relative = path.relative_to(vendor).as_posix()
    lines.append(f"// FILE: {relative}")
    lines.append(f"// HEX: {path.read_bytes().hex()}")

output.parent.mkdir(parents=True, exist_ok=True)
output.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"Embedded {sum(1 for p in vendor.rglob('*') if p.is_file())} Opus source files in {output}")
